function generateRecommendations(productList) {
  const rankedProducts = [];
  for (let i = 1; i <= 5; i++) { // Generate recommendations for the top 5
    const recommendation = {
      "rankedProducts": [],
    };
    for (let j = 0; j < productList.length; j++) {
      if (productList[j].name === productList[i - 1].name) {
        recommendation.rankedProducts.push(productList[j].name);
      }
    }
    rankedProducts.push(recommendation);
  }
  return rankedProducts.join("\n"); // Join the array elements into a string with newline characters
}
```
